(function (global) {
  'use strict';
  var pack = {"manifest":{"id":"drilling-failure","sceneId":"d4","title":"钻具失效预测","status":"ready","version":"1.0.0","updated":"2026-10-23","methods":["ts"],"tabs":{"background":{"label":"专业背景","lede":"钻柱承担旋转与载荷传递，反复交变载荷可能导致疲劳。服役小时相同并不意味着退化状态相同；用历史退化指标估计趋势与剩余寿命，有助于把后续作业时长与检查计划联系起来。","judge":[{"label":"数据来源","value":"教学合成","desc":"固定种子，可导出核查"},{"label":"方法类型","value":"退化趋势与寿命外推","desc":"纯前端轻量计算"},{"label":"输出用途","value":"教学比较","desc":"不连接设备与现场系统"},{"label":"评价边界","value":"合成任务","desc":"不声称真实工程收益"}],"sections":[{"no":1,"en":"BUSINESS","title":"载荷历史与钻具退化","html":"<p>钻柱包括钻杆、底部钻具组合及其他驱动钻头的工具。扭转波动与振动可能影响连接和钻头。真实疲劳评价依赖应力、几何、材料、腐蚀和检查记录；本例用人为损伤指标说明载荷历史与剩余寿命关系，绝不从单一振动值推导真实断裂时刻。</p><figure class=\"figure\"><div style=\"overflow-x:auto\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 118\" role=\"img\" aria-label=\"载荷历史与钻具退化\" style=\"width:100%;min-width:560px;max-width:640px;display:block;margin:auto\"><rect x=\"18\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"105\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">服役载荷</text><text x=\"105\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">交变弯曲 / 扭转载荷</text><path d=\"M194 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"208\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"295\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">退化代理量</text><text x=\"295\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">已标定传感器假设</text><path d=\"M384 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"398\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"485\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">剩余寿命</text><text x=\"485\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">趋势到阈值的距离</text></svg></div><figcaption class=\"figcap\">业务关系示意，不是测量结果。窄屏可在图内横向滚动。</figcaption></figure>"},{"no":2,"en":"METHOD","title":"退化趋势与寿命外推","html":"<p>隐藏合成损伤随载荷倍率的三次方累积，传感器代理量叠加噪声。估计器看不到隐藏损伤或未来值，只在近期观测窗口最小二乘拟合直线，外推到教学阈值 1。窗口长度体现平滑与响应滞后的折中，寿命敏感性范围说明噪声怎样改变外推结果。实现不是经过钻具试验标定的疲劳定律。</p>"},{"no":3,"en":"DATA","title":"数据准备与评价切分","html":"<p>固定种子 20261025，每小时一条，共 161 条合成记录。可修改载荷倍率、观测时间、回归窗口和计划作业时长。现场数据需要钻具唯一标识、累计服役、载荷谱、检修、探伤及失效记录，未失效钻具属于删失样本，不能虚构准确失效标签。</p>"},{"no":4,"en":"LIMITS","title":"模型适用范围与工程约束","html":"<p>RUL 假设未来载荷与当前趋势保持不变。±2 残差标准差转成的范围仅用于敏感性分析，不是已校准置信区间。当前观测期还未见失效时，不报告真实 RUL 误差；只有失效已发生才回溯评价。教学阈值不是报废标准，模型不能代替探伤或作业决策。</p><p>专业资料与方法来源：</p><ul><li><a href=\"https://glossary.slb.com/terms/d/drillstring\" target=\"_blank\" rel=\"noopener noreferrer\">SLB：drillstring</a>：支持钻柱组成的定义。</li><li><a href=\"https://www.slb.com/-/media/files/drilling/brochure/drillstring-vib-br\" target=\"_blank\" rel=\"noopener noreferrer\">SLB：Drillstring Vibrations and Vibration Modeling</a>：支持扭转振动可能导致连接疲劳和钻头损伤的背景，不支持本例合成寿命系数。</li><li><a href=\"https://data.nasa.gov/dataset/prognostics\" target=\"_blank\" rel=\"noopener noreferrer\">NASA：Prognostics</a>：支持 RUL 为功能失效前剩余时间的概念；本例未使用 NASA 数据，不代表 NASA 方法复现。</li></ul>"}]},"workflow":{"label":"案例流程","title":"退化趋势与寿命外推","lead":["钻柱承担旋转与载荷传递，反复交变载荷可能导致疲劳。服役小时相同并不意味着退化状态相同；用历史退化指标估计趋势与剩余寿命，有助于把后续作业时长与检查计划联系起来。"],"stats":[["数据","固定种子合成"],["运行方式","浏览器本地"],["工程用途","方法教学"]],"steps":[{"name":"服役数据整理","role":"数据","do":"按钻具标识保留按时序排列的历史与检查记录。","effect":"形成可追溯退化序列。","trap":"真实数据需处理换件、检修及右删失。"},{"name":"局部退化回归","role":"算法","do":"仅用已观测窗口拟合时间与传感器代理量的斜率。","effect":"把噪声观测转换为趋势。","trap":"窗口短会抖动，长窗口会落后于工况变化。"},{"name":"阈值寿命外推","role":"算法","do":"正斜率时计算到阈值的时间，非正斜率不输出有限寿命。","effect":"与后续计划时长形成条件对比。","trap":"趋势外推不能保证未来载荷不变。"},{"name":"回溯误差与检查","role":"评价","do":"失效已观测后，对此前多个起点计算预测 RUL 与真实剩余小时差。","effect":"区分在线预测与事后评价。","trap":"同一钻具的多个起点不是独立测试样本。"}],"metrics":{"title":"计算指标与评价边界","html":"<figure class=\"figure\"><div style=\"overflow-x:auto\"><svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 600 118\" role=\"img\" aria-label=\"案例计算流程\" style=\"width:100%;min-width:560px;max-width:640px;display:block;margin:auto\"><rect x=\"18\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"105\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">历史窗口</text><text x=\"105\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">仅当前及过去观测</text><path d=\"M194 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"208\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"295\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">退化趋势外推</text><text x=\"295\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">斜率 / 阈值 / 敏感性</text><path d=\"M384 59h12m-5-5 5 5-5 5\" fill=\"none\" stroke=\"var(--jade,#2f7d6b)\" stroke-width=\"2\"/><rect x=\"398\" y=\"18\" width=\"174\" height=\"82\" rx=\"8\" fill=\"var(--jade-l,#e6f1ec)\" stroke=\"var(--line-2,#ddd7c8)\"/><text x=\"485\" y=\"50\" text-anchor=\"middle\" font-size=\"18\" fill=\"var(--ink,#242b2e)\">寿命与检查</text><text x=\"485\" y=\"79\" text-anchor=\"middle\" font-size=\"15\" fill=\"var(--ink-2,#4d565b)\">删失标记 / 回溯误差</text></svg></div><figcaption class=\"figcap\">输入、计算与评价之间的关系示意；结果由演示实际计算。</figcaption></figure><p>RUL=max(0,(1−当前拟合退化量)/正斜率)，单位 h。已观测隐藏损伤首次达到 1 的小时为合成失效时刻；失效已知后，每隔 5 h 的历史起点分别只用当时窗口预测，以平均绝对误差评价。未观测到失效时显示右删失，不报告 MAE。多个起点共享同一序列，不能当跨钻具泛化结果。</p>"},"fails":[{"name":"数据分布变化","why":"RUL 假设未来载荷与当前趋势保持不变。±2 残差标准差转成的范围仅用于敏感性分析，不是已校准置信区间。当前观测期还未见失效时，不报告真实 RUL 误差；只有失效已发生才回溯评价。教学阈值不是报废标准，模型不能代替探伤或作业决策。"},{"name":"合成结果误用","why":"所有数据、参数范围、阈值和响应系数均为教学合成设定；资料只支持业务定义和方法动机，不支持本例数值与现场收益。"}]},"demo":{"mode":"page","html":"demo/index.html","js":"demo/demo.js","label":"案例演示","height":1200,"intro":"钻柱承担旋转与载荷传递，反复交变载荷可能导致疲劳。服役小时相同并不意味着退化状态相同；用历史退化指标估计趋势与剩余寿命，有助于把后续作业时长与检查计划联系起来。"}}},"files":[{"name":"demo/demo.css","size":3674,"enc":"text","data":":root{font:16px/1.8 -apple-system,BlinkMacSystemFont,\"Segoe UI\",\"Microsoft YaHei\",sans-serif;color:#242b2e;background:#fbfaf6;--jade:#2f7d6b;--line:#ddd7c8;--muted:#56646b}\n*{box-sizing:border-box}body{margin:0}main{max-width:1200px;margin:auto;padding:24px}h1,h2,h3,p{margin:0}h1{font-size:clamp(24px,3vw,32px);line-height:1.4;margin:12px 0}h2{font-size:21px;line-height:1.5;margin-bottom:12px}h3{font-size:18px;margin:20px 0 10px}p{color:var(--muted)}header{margin-bottom:24px}header p{max-width:80ch}.badge{font-size:14px;color:#235f51;background:#e6f1ec;border-radius:4px;padding:5px 9px}.experiment{display:grid;grid-template-columns:285px minmax(0,1fr);border:1px solid var(--line);border-radius:12px;overflow:hidden;background:white}aside{background:#f3f5f0;padding:22px;border-right:1px solid var(--line)}.field{display:block;margin:18px 0}.field>span{display:flex;flex-wrap:wrap;justify-content:space-between;gap:6px;font-weight:600}.field output{color:var(--jade);font-variant-numeric:tabular-nums}input,select,button{font:inherit}input[type=range]{width:100%;accent-color:var(--jade);margin:14px 0;cursor:pointer}select{display:block;width:100%;min-height:44px;margin:8px 0;border:1px solid var(--line);border-radius:5px;background:white;padding:7px}small,.hint,.boundary{font-size:14px;color:var(--muted);line-height:1.75}.boundary{margin-top:18px;border-top:1px solid var(--line);padding-top:12px}button{min-height:44px;padding:8px 14px;color:white;background:var(--jade);border:1px solid var(--jade);border-radius:6px;cursor:pointer}button.quiet{background:white;color:var(--jade);border-color:var(--line)}button[hidden]{display:none}button:hover{filter:brightness(.95)}:focus-visible{outline:3px solid #41699b;outline-offset:3px}.results{padding:24px;min-width:0}.metrics{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.metrics>div{padding:12px 14px;background:#f5f7f4;border:1px solid #e3e8e4;border-radius:6px}.metrics span{display:block;font-size:14px;color:var(--muted)}.metrics strong{display:block;font-size:23px;font-weight:600;line-height:1.5;color:#235f51;font-variant-numeric:tabular-nums}#status{padding:14px 0;font-size:15px}#apply{margin-bottom:16px}.chart{border-top:1px solid var(--line);padding-top:22px;margin-top:22px}.chart p{font-size:15px;line-height:1.8}.chart-scroll,.table-scroll{overflow:auto;overscroll-behavior-x:contain;padding-bottom:6px}svg{width:100%;max-width:700px;height:auto;display:block;margin:12px auto 4px}svg text{font:16px -apple-system,BlinkMacSystemFont,\"Microsoft YaHei\",sans-serif;fill:var(--muted)}.legend{display:flex;gap:10px 18px;flex-wrap:wrap;font-size:14px}.legend span{display:flex;align-items:center;gap:7px}.legend i{display:block;width:14px;height:4px}.details{margin-top:28px}.details>p{max-width:95ch}table{width:100%;border-collapse:collapse;font-size:15px;font-variant-numeric:tabular-nums}th,td{text-align:left;padding:9px 12px;border-bottom:1px solid var(--line);white-space:nowrap}th{background:#f3f5f0;font-weight:600}#download{margin-top:18px}footer{font-size:14px;color:var(--muted);padding:18px 0;margin-top:26px;border-top:1px solid var(--line)}\n@media(max-width:1000px){.experiment{grid-template-columns:1fr}aside{border-right:0;border-bottom:1px solid var(--line)}#controls{display:grid;grid-template-columns:1fr 1fr;gap:0 24px}.field{margin:10px 0}}\n@media(max-width:600px){main{padding:12px}.results,aside{padding:16px}#controls{grid-template-columns:1fr}.metrics{gap:8px}.metrics strong{font-size:20px}.chart-scroll svg{width:640px;max-width:none}.badge{display:inline-block;font-size:13px}}\n@media(prefers-reduced-motion:reduce){*{scroll-behavior:auto!important}}\n"},{"name":"demo/demo.js","size":3704,"enc":"text","data":"(function(){\n  'use strict';const M=FailureModel,F=CaseUI.f;\n  CaseUI.mount({id:'drilling-failure',title:'钻具失效预测',intro:'载荷越高，教学损伤累积越快。使用已观测的噪声退化指标拟合局部趋势，外推到失效阈值，比较计划作业时长与预测剩余寿命。',boundary:'退化指标是假定可测且已标定的合成代理量，不等同于振动 RMS 或真实裂纹尺寸。未模拟腐蚀、冲击及连接失效。',controls:[{id:'load',label:'等效载荷倍率',min:.8,max:1.6,step:.1,value:1.3},{id:'time',label:'已观测服役时间',min:20,max:160,step:1,value:70,unit:'h'},{id:'window',label:'局部回归窗口',min:6,max:30,step:1,value:16,unit:'条'},{id:'plan',label:'后续计划作业',min:5,max:100,step:5,value:30,unit:'h'}],method:'种子 20261025，161 条每小时记录。隐藏损伤每小时按 0.0035×载荷³×(1+0.12 sin(t/12)) 累积；初始损伤 0.08、失效阈值 1 均人为设定。估计器只能访问当前及历史噪声传感器代理量，窗口最小二乘拟合直线，RUL=(1−当前拟合指标)/正斜率。±2 残差标准差只作敏感性范围，不是经过标定的置信区间。只有已经观测到合成失效后，才回溯计算多个较早起点的 RUL MAE；否则明确显示右删失。',\n    compute:s=>{const full=M.generate(s.load),rows=full.slice(0,s.time+1),e=M.estimate(rows,s.time,s.window),v=M.evaluate(rows,s.window,s.time),failed=rows.find(r=>r.damage>=1),horizon=Math.min(300,s.time+(e.high??100)+20),forecast=[];for(let t=s.time;t<=horizon;t+=2)forecast.push([t,e.intercept+e.slope*t]);\n      return {metrics:[['估计剩余寿命',e.rul===null?'无法外推':F(e.rul,1)+' h'],['敏感性范围',e.low===null?'不可定义':F(e.low,1)+'–'+F(e.high,1)+' h'],['回溯 RUL MAE',v.mae===null?'失效未观测，右删失':F(v.mae,1)+' h'],['回溯起点数',String(v.n)]],summary:failed?`合成隐藏损伤已在 ${failed.t} h 达到教学失效阈值；此时不再给出继续服役建议。`:e.rul===null?'窗口斜率非正，不能给出有限剩余寿命。':`计划 ${s.plan} h，${e.low!==null&&e.low<s.plan?'超过寿命敏感性范围的下端，提示安排人工检查':'未超过敏感性范围下端，仍需结合检查记录'}。预测假设未来载荷和退化趋势保持不变。`,\n        plots:[{title:'退化观测与寿命外推',xLabel:'服役时间 h',yLabel:'归一化退化指标',xRange:[0,horizon],yRange:[0,Math.max(1.3,...forecast.map(r=>r[1]),...rows.map(r=>r.sensor))],hlines:[1],vlines:[s.time],note:'绿点为已观测代理量，蓝线为局部趋势外推，红虚线为教学阈值。未来隐藏损伤不传入估计器，也不显示。',series:[{name:'历史传感器代理量',dots:true,points:rows.map(r=>[r.t,r.sensor])},{name:'局部趋势外推',dashed:true,points:forecast}]},\n        {title:'历次剩余寿命估计',xLabel:'当时已观测时间 h',yLabel:'预测 RUL h',note:'每个起点单独截取当时历史拟合；曲线波动反映窗口噪声影响。寿命值是模型条件外推。',series:[{name:'历史 RUL 预测',points:rows.filter(r=>r.t>=20).map(r=>[r.t,M.estimate(rows,r.t,s.window).rul]).filter(r=>r[1]!==null)}]}],\n        table:{title:'近期窗口拟合记录',headers:['时刻 h','已观测代理量','拟合值','残差'],rows:rows.slice(-s.window).map(r=>[r.t,F(r.sensor,4),F(e.intercept+e.slope*r.t,4),F(r.sensor-e.intercept-e.slope*r.t,4)]),note:`当前斜率 ${F(e.slope,5)} /h，残差标准差 ${F(e.sigma,4)}；MAE 只在已知失效时使用，不把尚未失效的序列当作无限寿命。`},records:rows.map(r=>({hour:r.t,sensor_proxy:r.sensor,fitted:e.intercept+e.slope*r.t}))};}\n  });\n})();\n"},{"name":"demo/index.html","size":416,"enc":"text","data":"<!doctype html>\n<html lang=\"zh-CN\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>钻具失效预测</title><link rel=\"stylesheet\" href=\"demo.css\"></head><body><main id=\"app\"></main><noscript>需要启用 JavaScript 才能运行本地计算。</noscript><script src=\"model.js\"></script><script src=\"ui.js\"></script><script src=\"demo.js\"></script></body></html>"},{"name":"demo/model.js","size":1852,"enc":"text","data":"(function(g){\n  'use strict';\n  function generate(load){\n    let seed=20261025;const rand=()=>{seed=(1664525*seed+1013904223)>>>0;return seed/4294967296;};\n    let damage=.08;return Array.from({length:161},(_,t)=>{\n      const rate=.0035*load**3*(1+.12*Math.sin(t/12));if(t)damage+=rate;\n      // Damage is hidden from the estimator; the sensor is a noisy calibrated proxy.\n      return {t,damage,sensor:damage+(rand()-.5)*.035,rate};\n    });\n  }\n  function estimate(rows,time,window){\n    const observed=rows.filter(r=>r.t<=time),recent=observed.slice(-window);\n    const n=recent.length,mx=recent.reduce((s,r)=>s+r.t,0)/n,my=recent.reduce((s,r)=>s+r.sensor,0)/n;\n    const xx=recent.reduce((s,r)=>s+(r.t-mx)**2,0);\n    const slope=xx?recent.reduce((s,r)=>s+(r.t-mx)*(r.sensor-my),0)/xx:0,intercept=my-slope*mx;\n    const current=intercept+slope*time;\n    const sigma=n>2?Math.sqrt(recent.reduce((s,r)=>s+(r.sensor-intercept-slope*r.t)**2,0)/(n-2)):0;\n    const rul=current>=1?0:slope>1e-8?Math.max(0,(1-current)/slope):null;\n    // ±2 residual SD is a sensitivity band, NOT a calibrated confidence interval.\n    return {slope,intercept,current,sigma,rul,low:slope>1e-8?Math.max(0,(1-current-2*sigma)/slope):null,high:slope>1e-8?Math.max(0,(1-current+2*sigma)/slope):null};\n  }\n  function evaluate(rows,window,cutoff){\n    const fail=rows.find(r=>r.damage>=1);if(!fail||fail.t>cutoff)return {mae:null,n:0,fail:null};\n    const errors=[];for(let t=Math.max(window,20);t<fail.t;t+=5){const e=estimate(rows,t,window);if(e.rul!==null)errors.push(Math.abs(e.rul-(fail.t-t)));}\n    return {mae:errors.length?errors.reduce((a,b)=>a+b,0)/errors.length:null,n:errors.length,fail:fail.t};\n  }\n  const api={generate,estimate,evaluate};if(typeof module!=='undefined')module.exports=api;else g.FailureModel=api;\n})(typeof window!=='undefined'?window:globalThis);\n"},{"name":"demo/ui.js","size":6241,"enc":"text","data":"(function(g){\n  'use strict';\n  const esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\n  const f=(v,n=2)=>v===null||!Number.isFinite(v)?'不可定义':v.toFixed(n);\n  function plot(p,index){\n    const W=700,H=340,L=85,R=24,T=38,B=64;\n    const all=p.series.flatMap(s=>s.points).filter(a=>a.every(Number.isFinite));\n    const extent=(k)=>{const v=all.map(a=>a[k]);let a=Math.min(...v),b=Math.max(...v);if(a===b){a-=1;b+=1;}return [a,b];};\n    const xr=p.xRange||extent(0),yr=p.yRange||extent(1),x=v=>L+(v-xr[0])/(xr[1]-xr[0])*(W-L-R),y=v=>H-B-(v-yr[0])/(yr[1]-yr[0])*(H-T-B);\n    let svg=`<defs><clipPath id=\"clip${index}\"><rect x=\"${L}\" y=\"${T}\" width=\"${W-L-R}\" height=\"${H-T-B}\"/></clipPath></defs>`;\n    for(let i=0;i<=4;i++){const xv=xr[0]+(xr[1]-xr[0])*i/4,yv=yr[0]+(yr[1]-yr[0])*i/4;svg+=`<path d=\"M${L} ${y(yv)}H${W-R}\" stroke=\"#e3e8e4\"/><text x=\"${L-10}\" y=\"${y(yv)+5}\" text-anchor=\"end\">${f(yv,p.decimals??1)}</text><text x=\"${x(xv)}\" y=\"${H-B+27}\" text-anchor=\"middle\">${f(xv,p.xDecimals??0)}</text>`;}\n    svg+=`<text x=\"${L}\" y=\"22\">${esc(p.yLabel)}</text><text x=\"${(L+W-R)/2}\" y=\"${H-8}\" text-anchor=\"middle\">${esc(p.xLabel)}</text><g clip-path=\"url(#clip${index})\">`;\n    (p.bands||[]).forEach(b=>{svg+=`<rect x=\"${x(b.from)}\" y=\"${T}\" width=\"${x(b.to)-x(b.from)}\" height=\"${H-T-B}\" fill=\"#f8ecdf\"/>`;});\n    (p.hlines||[]).forEach(v=>svg+=`<path d=\"M${L} ${y(v)}H${W-R}\" stroke=\"#a34138\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>`);\n    (p.vlines||[]).forEach(v=>svg+=`<path d=\"M${x(v)} ${T}V${H-B}\" stroke=\"#8e5229\" stroke-width=\"2\" stroke-dasharray=\"6 5\"/>`);\n    const colors=['#2f7d6b','#41699b','#b26a39','#7e5a8d'];\n    p.series.forEach((s,i)=>{const pts=s.points.filter(a=>a.every(Number.isFinite)),color=s.color||colors[i%4];if(s.dots)pts.forEach(a=>svg+=`<circle cx=\"${x(a[0])}\" cy=\"${y(a[1])}\" r=\"3.5\" fill=\"${color}\" opacity=\".65\"><title>${esc(s.name)}：${f(a[0])}, ${f(a[1])}</title></circle>`);else svg+=`<path d=\"${pts.map((a,j)=>(j?'L':'M')+x(a[0])+','+y(a[1])).join(' ')}\" fill=\"none\" stroke=\"${color}\" stroke-width=\"2.5\" ${s.dashed?'stroke-dasharray=\"7 5\"':''}/>`;});svg+='</g>';\n    return `<article class=\"chart\"><h2>${esc(p.title)}</h2><p>${esc(p.note)}</p><div class=\"chart-scroll\" role=\"region\" tabindex=\"0\" aria-label=\"${esc(p.title)}，窄屏可横向滚动\"><svg viewBox=\"0 0 ${W} ${H}\" role=\"img\" aria-label=\"${esc(p.title+'；'+p.yLabel+'；'+p.xLabel)}\">${svg}</svg></div><div class=\"legend\">${p.series.map((s,i)=>`<span><i style=\"background:${s.color||colors[i%4]}\"></i>${esc(s.name)}</span>`).join('')}</div></article>`;\n  }\n  function mount(c){\n    const root=document.getElementById('app');let result;\n    root.innerHTML=`<header><span class=\"badge\">教学合成数据 · 本地计算 · 固定种子</span><h1>${esc(c.title)}</h1><p>${esc(c.intro)}</p></header><section class=\"experiment\"><aside><h2>实验设置</h2><form id=\"controls\">${c.controls.map(a=>`<label class=\"field\" for=\"${a.id}\"><span>${esc(a.label)} <output id=\"${a.id}-value\"></output></span>${a.options?`<select id=\"${a.id}\">${a.options.map(o=>`<option value=\"${esc(o[0])}\">${esc(o[1])}</option>`).join('')}</select>`:`<input id=\"${a.id}\" type=\"range\" min=\"${a.min}\" max=\"${a.max}\" step=\"${a.step}\" value=\"${a.value}\">`}<small>${esc(a.hint||'')}</small></label>`).join('')}</form><button id=\"reset\" class=\"quiet\" type=\"button\">恢复初始设置</button><p class=\"boundary\">${esc(c.boundary)}</p></aside><div class=\"results\"><h2>计算结果</h2><div id=\"metrics\" class=\"metrics\"></div><p id=\"status\" role=\"status\"></p><button id=\"apply\" type=\"button\" hidden>应用推荐参数</button><div id=\"plots\"></div></div></section><section class=\"details\"><h2>方法与评价边界</h2><p>${esc(c.method)}</p><div id=\"table\"></div><button id=\"download\" class=\"quiet\" type=\"button\">导出当前实验 CSV</button></section><footer>所有范围、阈值、响应系数和目标均为教学设置；合成评价不能证明现场效果。演示不连接设备。图表可通过下方数据表及 CSV 核对。</footer>`;\n    const read=()=>Object.fromEntries(c.controls.map(a=>[a.id,a.options?document.getElementById(a.id).value:+document.getElementById(a.id).value]));\n    function render(){const s=read();c.controls.forEach(a=>document.getElementById(a.id+'-value').textContent=a.options?'':s[a.id]+(a.unit?' '+a.unit:''));result=c.compute(s);document.getElementById('metrics').innerHTML=result.metrics.map(a=>`<div><span>${esc(a[0])}</span><strong>${esc(a[1])}</strong></div>`).join('');document.getElementById('status').textContent=result.summary;document.getElementById('plots').innerHTML=result.plots.map(plot).join('');const table=result.table;document.getElementById('table').innerHTML=`<h3>${esc(table.title)}</h3><div class=\"table-scroll\"><table><thead><tr>${table.headers.map(v=>`<th scope=\"col\">${esc(v)}</th>`).join('')}</tr></thead><tbody>${table.rows.map(r=>`<tr>${r.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class=\"hint\">${esc(table.note||'')}</p>`;document.getElementById('apply').hidden=!result.apply;}\n    document.getElementById('controls').addEventListener('submit',e=>e.preventDefault());\n    c.controls.forEach(a=>document.getElementById(a.id).addEventListener(a.options?'change':'input',render));\n    document.getElementById('reset').onclick=()=>{c.controls.forEach(a=>document.getElementById(a.id).value=a.value);render();};\n    document.getElementById('apply').onclick=()=>{if(result.apply){Object.entries(result.apply).forEach(([k,v])=>document.getElementById(k).value=v);render();}};\n    document.getElementById('download').onclick=()=>{const rows=result.records;if(!rows.length)return;const keys=Object.keys(rows[0]),cell=v=>'\"'+String(v??'').replace(/\"/g,'\"\"')+'\"';const csv='\\uFEFF'+[keys,...rows.map(r=>keys.map(k=>r[k]))].map(r=>r.map(cell).join(',')).join('\\r\\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=c.id+'-synthetic.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};\n    c.controls.forEach(a=>document.getElementById(a.id).value=a.value);render();\n  }\n  g.CaseUI={mount,f,plot};\n})(window);\n"}]};
  // Local uploads take precedence. Keep the original importer and its package contract.
  var sc = global.ATLAS.index.byScene[pack.manifest.sceneId];
  var existing = global.Cases.get(pack.manifest.id);
  if (existing) {
    if (sc && existing.tabs && existing.tabs.demo) sc.demo = true;
    return;
  }
  if (global.CaseImport.blockedList().indexOf(pack.manifest.id) >= 0) return;
  var c = pack.manifest;
  var cfg = c.tabs.demo;
  var handle = null;
  c.status = 'ready';
  c.tabs.demo = {
    label: cfg.label, intro: cfg.intro,
    mount: function (root, ctx) {
      handle = global.CaseDemoHost.create(root, { files: pack.files, demo: cfg, meta: c }, ctx);
    },
    unmount: function () { if (handle) { handle.destroy(); handle = null; } }
  };
  global.Cases.register(c);
  if (sc) sc.demo = true;
})(window);
